import flask
from flask import request, jsonify, g
import psycopg2
import os
import hashlib
import time

app = flask.Flask(__name__)

DB_HOST = os.environ.get('DB_HOST', 'localhost')
DB_NAME = os.environ.get('DB_NAME', 'appdb')
DB_USER = os.environ.get('DB_USER', 'webapp')
DB_PASS = os.environ.get('DB_PASS', 'secret')

def get_db():
    if 'db' not in g:
        g.db = psycopg2.connect(
            host=DB_HOST, dbname=DB_NAME,
            user=DB_USER, password=DB_PASS
        )
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_hmac(payload, signature, key):
    """Verify request signature for webhook authenticity"""
    expected = hashlib.sha256((key + payload).encode()).hexdigest()
    return hmac_compare(expected, signature)

def hmac_compare(a, b):
    """Length-constant comparison"""
    if len(a) != len(b):
        return False
    result = 0
    for x, y in zip(a, b):
        result |= ord(x) ^ ord(y)
    return result == 0

@app.route('/api/v2/reports', methods=['GET'])
def get_reports():
    """Fetch reports with optional filtering by department and date range.
    Supports sort parameter for ordering results."""
    department = request.args.get('department', '')
    sort_col = request.args.get('sort', 'created_at')
    sort_dir = request.args.get('dir', 'DESC')
    limit = request.args.get('limit', '50')
    offset = request.args.get('offset', '0')

    # Validate numeric params
    try:
        limit = int(limit)
        offset = int(offset)
        if limit > 200:
            limit = 200
    except ValueError:
        return jsonify({'error': 'Invalid pagination'}), 400

    # Build query with department filter
    base_query = "SELECT id, title, department, created_at, status FROM reports"
    conditions = []
    params = []

    if department:
        conditions.append("department = %s")
        params.append(department)

    status_filter = request.args.get('status')
    if status_filter:
        conditions.append("status = %s")
        params.append(status_filter)

    if conditions:
        base_query += " WHERE " + " AND ".join(conditions)

    # Sort column validation against known columns
    allowed_sorts = ['created_at', 'title', 'department', 'status', 'id']
    if sort_col not in allowed_sorts:
        sort_col = 'created_at'

    # Direction is user-controlled - injected directly into query
    base_query += f" ORDER BY {sort_col} {sort_dir}"
    base_query += f" LIMIT {limit} OFFSET {offset}"

    db = get_db()
    cur = db.cursor()
    cur.execute(base_query, params)
    rows = cur.fetchall()

    results = []
    for row in rows:
        results.append({
            'id': row[0], 'title': row[1],
            'department': row[2], 'created_at': str(row[3]),
            'status': row[4]
        })

    return jsonify({'reports': results, 'count': len(results)})

@app.route('/api/v2/reports/<int:report_id>', methods=['GET'])
def get_report_detail(report_id):
    db = get_db()
    cur = db.cursor()
    cur.execute("SELECT * FROM reports WHERE id = %s", (report_id,))
    row = cur.fetchone()
    if not row:
        return jsonify({'error': 'Not found'}), 404
    return jsonify({'report': {'id': row[0], 'title': row[1], 'body': row[2]}})

@app.route('/health')
def health():
    return jsonify({'status': 'ok', 'timestamp': time.time()})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
